INSERT INTO award_type (name, show_division, description) VALUES
	('MVP', true, 'Den spelaren som varit bäst och mest avgörande under både grundserie och slutspel.'),
	('Grand Finals MVP', true, 'De två bästa spelarna, en från varje lag, som tävlar i finalen enligt finallagen själva.'),
	('Underdog MVP', true, 'Spelaren som trots placering i den lägre halvan av tabellen bjudit på imponerande insatser genom turneringen. Alternativt en spelare med lägre rank än många av hens motståndare, som bjudit på bra insatser genom turneringen.'),
	('Most Improved Player', true, NULL),
	('Rookie', true, NULL),
	('Community MVP', true, NULL),
	('Steget Upp Award', true, NULL),
	('Role Star - DPS', true, 'Utses till de spelare som varit extra duktiga inom rollen DPS.'),
	('Role Star - Tank', true, 'Utses till de spelare som varit extra duktiga inom rollen Tank.'),
	('Role Star - Support', true, 'Utses till de spelare som varit extra duktiga inom rollen Support.'),
	('Tittarnas Favorit Award', false, NULL),
	('Tittarnas Favorit-Duo Award', false, NULL),
	('Ligaledningens Caster Award', false, NULL),
	('Hall of Fame 2024', false, NULL),
	('Hall of Fame 2025', false, NULL)
ON CONFLICT (name) DO NOTHING;

