INSERT INTO player_award (award_type_id, player_id, division_id, motivation)
SELECT at.id, ad.player_id, ad.division_id, ad.motivation
FROM award_data ad
JOIN award_type at ON at.name = ad.award_type_name
WHERE NOT EXISTS (
	SELECT 1
	FROM player_award pa
	WHERE pa.award_type_id = at.id
		AND pa.player_id = ad.player_id
		AND pa.division_id IS NOT DISTINCT FROM ad.division_id
);

COMMIT;

